		foreach ($inv as $i) print "<tr><td class=\"vr-nm\"><a>".bp_h($i['name'] ?: $i['email'])."</a><small>".bp_h($i['email'])."</small></td><td class=\"vr-mut\">".($i['kind'] == 'employee' ? bp_t('Medarbejder','Employee').($i['partner_role'] == 'owner' ? ' ('.bp_t('ejer','owner').')' : '') : bp_t('Kundebruger','Customer user').($i['regnskab'] ? ' · '.bp_h($i['regnskab']) : '').($i['replaces_user_id'] ? ' · '.bp_t('udskiftning','replacement') : ''))."</td><td class=\"vr-mut\">".bp_date($i['sent_at'])." <span class=\"vr-mut2\">· ".bp_h($i['by_login'])."</span></td><td class=\"vr-mut\">".bp_date($i['expires_at'])."</td><td><span class=\"vr-st\"><span class=\"vr-dot ".$stTxt[$i['status']][1]."\"></span>".$stTxt[$i['status']][0]."</span></td><td class=\"vr-r\" style=\"white-space:nowrap\">".(in_array($i['status'], array('sent','expired')) ? "<form method=\"post\" style=\"display:inline\"><input type=\"hidden\" name=\"bp_action\" value=\"inv_resend\"><input type=\"hidden\" name=\"id\" value=\"".(int)$i['id']."\"><button type=\"submit\" class=\"vr-link\">".bp_t('Gensend','Resend')."</button></form>" : "").($i['status'] == 'sent' ? " · <form method=\"post\" style=\"display:inline\"><input type=\"hidden\" name=\"bp_action\" value=\"inv_revoke\"><input type=\"hidden\" name=\"id\" value=\"".(int)$i['id']."\"><button type=\"submit\" class=\"vr-link\">".bp_t('Tilbagekald','Revoke')."</button></form>" : "")."</td></tr>";
		if (!$inv) print "<tr><td colspan=\"6\" class=\"vr-mut\" style=\"padding:20px\">".bp_t('Ingen invitationer endnu.','No invitations yet.')."</td></tr>";
		print "</tbody></table><div class=\"vr-foot\"><span>".bp_t('Gensend forlænger gyldigheden med','Resend extends validity by')." ".BP_INVITE_DAYS." ".bp_t('dage. Udskiftning af en kundebruger: brug Udskift på kundens Brugere-fane.','days. To replace a customer user, use Replace on the customer\'s Users tab.')."</span></div></div></section>";
	}
	if (bp_can('create')) {
		$reqs = bp_access_requests(); $rt = array('open' => array(bp_t('Afventer svar','Awaiting reply'), 'vr-warn'), 'approved' => array(bp_t('Godkendt','Approved'), 'vr-ok'), 'rejected' => array(bp_t('Afvist','Rejected'), 'vr-bad'), 'cancelled' => array(bp_t('Trukket tilbage','Cancelled'), 'vr-off'), 'expired' => array(bp_t('Udløbet','Expired'), 'vr-bad'));
		print "<section class=\"vr-sect\" id=\"anmodninger\" style=\"margin-top:22px\"><h2>".bp_t('Anmodninger om adgang til eksisterende regnskaber','Access requests for existing accounts')." <small>".count(array_filter($reqs, fn($r) => $r['status'] == 'open'))." ".bp_t('åbne','open')."</small></h2><div class=\"vr-card\"><table class=\"vr-t\"><thead><tr><th>".bp_t('Regnskab','Account')."</th><th>".bp_t('Sendt til','Sent to')."</th><th>".bp_t('Sendt','Sent')."</th><th>".bp_t('Status','Status')."</th><th></th></tr></thead><tbody>";
		foreach ($reqs as $r) print "<tr><td class=\"vr-nm\"><a>".bp_h($r['regnskab'])."</a>".($r['message'] ? "<small>".bp_h($r['message'])."</small>" : "")."</td><td class=\"vr-mut\">".($r['sent_to'] == bp_saldi_mail() ? 'Saldi' : bp_h($r['sent_to']))."</td><td class=\"vr-mut\">".bp_date($r['sent_at'])." <span class=\"vr-mut2\">· ".bp_h($r['by_login'])."</span></td><td><span class=\"vr-st\"><span class=\"vr-dot ".$rt[$r['status']][1]."\"></span>".$rt[$r['status']][0].($r['decided_by'] ? ' <span class="vr-mut2">· '.bp_h($r['decided_by']).'</span>' : '')."</span></td><td class=\"vr-r\" style=\"white-space:nowrap\">".($r['status'] == 'open' ? "<form method=\"post\" style=\"display:inline\"><input type=\"hidden\" name=\"bp_action\" value=\"req_resend\"><input type=\"hidden\" name=\"id\" value=\"".(int)$r['id']."\"><button type=\"submit\" class=\"vr-link\">".bp_t('Gensend','Resend')."</button></form> · <form method=\"post\" style=\"display:inline\"><input type=\"hidden\" name=\"bp_action\" value=\"req_cancel\"><input type=\"hidden\" name=\"id\" value=\"".(int)$r['id']."\"><button type=\"submit\" class=\"vr-link\">".bp_t('Træk tilbage','Cancel')."</button></form>" : "")."</td></tr>";
		if (!$reqs) print "<tr><td colspan=\"5\" class=\"vr-mut\" style=\"padding:20px\">".bp_t('Ingen anmodninger endnu.','No requests yet.')." <a href=\"bogholder_opret.php?tab=tilknyt\">".bp_t('Tilknyt et regnskab','Link an account')."</a></td></tr>";
		print "</tbody></table></div></section>";
	}

} elseif ($tab == 'priser' && bp_is_group()) {
