	print "<div class=\"vr-foot\"><span>".bp_t('Hver aktiv medarbejder i koncernen tæller som én ERP-bruger, uanset hvor mange selskaber vedkommende arbejder i.','Each active employee in the group counts as one ERP user, however many companies they work in.').($unpriced ? ' '.$unpriced.' '.bp_t('selskab(er) har pris efter aftale og er ikke med i summen.','company/companies are priced by agreement and are not in the total.') : '')."</span></div></div></section>";
	print "<section class=\"vr-sect\" style=\"margin-top:22px\"><h2>".bp_t('Selskaber på den samlede faktura','Companies on the combined invoice')." <small>".count($rows)."</small></h2><div class=\"vr-card\">";
	foreach ($rows as $x) { list($r, $pn, $m) = $x; print "<div class=\"bp-row\"><div><b><a href=\"bogholder_panel.php?regnskab_id=".(int)$r['id']."\">".bp_h($r['regnskab'])."</a></b><small>".($pn ? bp_h($pn) : bp_t('ingen pakke','no plan')).($r['is_home'] ? ' · '.bp_t('hovedselskab','parent company') : '')."</small></div><div class=\"bp-acts\"><span class=\"vr-mut\">".($m === null ? bp_t('efter aftale','by agreement') : bp_kr($m).'/'.bp_t('md.','mo.'))."</span></div></div>"; }
	if (!$rows) print "<div class=\"vr-empty\"><span>".bp_t('Ingen selskaber faktureres via hovedselskabet endnu.','No companies are invoiced via the parent yet.')."</span></div>";
	print "<div class=\"vr-foot\"><span>".bp_t('Selskaber, der betaler selv, står ikke her. Betaleren ændres under selskabets Handlinger.','Companies that pay themselves are not listed. The payer is changed under the company\'s Actions.')."</span></div></div></section>";

} elseif ($tab == 'priser') {
	$scheme = bp_scheme_rows(); list($n, $list, $pct, $total, $avg, $tier) = bp_price_calc(count($scheme)); $calcN = max(0, (int)if_isset($_GET, $n, 'n'));
	print "<section class=\"vr-sect\"><h2>".bp_t('Prisoverblik','Price overview')." <small>".bp_t('bogholderordningen: Finans-regnskaber firmaet betaler for','the scheme: Finans accounts the firm pays for')."</small>".(BP_PRICING_PROVISIONAL ? " <span class=\"bp-prov\">".bp_t('foreløbige satser – prisen er ikke fastsat endnu','provisional rates – the price is not decided yet')."</span>" : "")."</h2><div class=\"vr-card\"><div class=\"bp-calc-out\" style=\"border-top:0\"><div class=\"bp-price\"><span>".bp_t('Regnskaber i ordningen','Accounts in the scheme')."</span><b>$n</b></div><div class=\"bp-price\"><span>".bp_t('Samlet pr. måned','Total per month')."</span><b>".bp_kr($total)."<small>".bp_t('ekskl. moms','excl. VAT')."</small></b></div><div class=\"bp-price\"><span>".bp_t('Gennemsnit pr. regnskab','Average per account')."</span><b>".($n ? bp_kr($avg) : '–')."</b></div><div class=\"bp-price\"><span>".bp_t('Forventet afregning','Expected settlement')."</span><b>".bp_kr($total)."<small>".bp_date(date('Y-m-01', strtotime('+1 month')))."</small></b></div></div>";
	print "<div class=\"vr-foot\"><span>".bp_t('Mængderabat','Volume discount').": ".($pct + 0)." % ".bp_t('ved','at')." $n ".bp_t('regnskaber','accounts')." · ".bp_t('listepris','list price')." ".bp_kr($list)."/".bp_t('md.','mo.')." ".bp_t('pr. Finans-regnskab. Rabatten beregnes automatisk, når antallet ændres.','per Finans account. The discount follows the count automatically.')."</span></div></div></section>";
	print "<div class=\"vr-grid2\" style=\"margin-top:22px\"><section class=\"vr-sect\"><h2>".bp_t('Prisberegner','Price calculator')." <small>".bp_t('ændrer intet','changes nothing')."</small></h2><div class=\"vr-card\"><form method=\"get\" class=\"bp-calc\" style=\"border-top:0\"><input type=\"hidden\" name=\"tab\" value=\"priser\"><label>".bp_t('Antal Finans-regnskaber','Number of Finans accounts')."<input class=\"vr-inp\" type=\"number\" name=\"n\" min=\"0\" max=\"5000\" value=\"$calcN\" id=\"calcN\" oninput=\"calc()\"></label><button type=\"submit\" class=\"vr-btn vr-quiet\">".bp_t('Beregn','Calculate')."</button></form><div class=\"bp-calc-out\" id=\"calcOut\"></div>";
	$tiersJs = array(); foreach (bp_tiers() as $t) $tiersJs[] = array((int)$t['min_count'], $t['max_count'] === null ? null : (int)$t['max_count'], (float)$t['discount_pct']);
	print "<script>var TIERS=".json_encode($tiersJs).",LIST=$list,T=".json_encode(array('a' => bp_t('Regnskaber','Accounts'), 'b' => bp_t('Rabat','Discount'), 'c' => bp_t('Samlet pr. md.','Total per month'), 'd' => bp_t('Gennemsnit','Average'))).";function kr(o){return Math.round(o/100).toLocaleString('da-DK')+' kr.'}function calc(){var n=Math.max(0,parseInt(document.getElementById('calcN').value)||0),p=0;TIERS.forEach(function(t){if(n>=t[0]&&(t[1]===null||n<=t[1]))p=t[2]});var tot=Math.round(n*LIST*(1-p/100));document.getElementById('calcOut').innerHTML='<div class=\"bp-price\"><span>'+T.a+'</span><b>'+n+'</b></div><div class=\"bp-price\"><span>'+T.b+'</span><b>'+p+' %</b></div><div class=\"bp-price\"><span>'+T.c+'</span><b>'+kr(tot)+'</b></div><div class=\"bp-price\"><span>'+T.d+'</span><b>'+(n?kr(tot/n):'–')+'</b></div>';}calc();</script></div></section>";
	print "<section class=\"vr-sect\"><h2>".bp_t('Mængdetrin','Volume tiers')."</h2><div class=\"vr-card\"><table class=\"vr-t\"><thead><tr><th>".bp_t('Antal regnskaber','Accounts')."</th><th class=\"vr-r\">".bp_t('Rabat','Discount')."</th><th class=\"vr-r\">".bp_t('Pris pr. regnskab','Price per account')."</th></tr></thead><tbody>";
	foreach (bp_tiers() as $t) print "<tr".($tier && (int)$tier['id'] == (int)$t['id'] ? " style=\"background:var(--surface-2)\"" : "")."><td>".(int)$t['min_count'].($t['max_count'] === null ? '+' : ' – '.(int)$t['max_count']).($tier && (int)$tier['id'] == (int)$t['id'] ? ' <span class="vr-pill">'.bp_t('jeres trin','your tier').'</span>' : '')."</td><td class=\"vr-r vr-num\">".((float)$t['discount_pct'] + 0)." %</td><td class=\"vr-r vr-num\">".bp_kr((int)round($list * (1 - (float)$t['discount_pct'] / 100)))."</td></tr>";
	print "</tbody></table><div class=\"vr-foot\"><span>".bp_t('Satserne er foreløbige, indtil Saldi har fastsat prisen for bogholderordningen. Priserne gælder Finans; større pakker faktureres kunden direkte.','The rates are provisional until Saldi sets the scheme price. The prices cover Finans; larger plans are invoiced to the customer directly.')."</span></div></div></section></div>";
	print "<section class=\"vr-sect\" style=\"margin-top:22px\"><h2>".bp_t('Regnskaber i ordningen','Accounts in the scheme')." <small>".count($scheme)."</small></h2><div class=\"vr-card\">"; foreach ($scheme as $r) print "<div class=\"bp-row\"><div><b><a href=\"bogholder_panel.php?regnskab_id=".(int)$r['id']."\">".bp_h($r['regnskab'])."</a></b><small>".bp_plan_html($r)." · ".bp_status_html($r)."</small></div><div class=\"bp-acts\"><span class=\"vr-mut\">".bp_kr((int)round($list * (1 - $pct / 100)))."/".bp_t('md.','mo.')."</span></div></div>"; if (!$scheme) print "<div class=\"vr-empty\"><span>".bp_t('Ingen regnskaber i ordningen endnu. Vælg "Firmaet betaler" ved oprettelse, eller overtag betalingen fra kundens kort.','No accounts in the scheme yet. Choose "The firm pays" when creating, or take over payment from the customer card.')."</span></div>"; print "</div></section>";

} elseif ($tab == 'fakturaer') {
	include("../includes/saldiBillingApi.php"); bill_cache_ensure();
	$search = ''; if ($p['home_regnskab_id']) { $bc = bill_get((int)$p['home_regnskab_id']); $search = $bc['billing_kontonr']; } if (!$search) $search = $p['cvr'] ?: $p['name'];
	$data = bill_fetch($search); $c = $data['customer'] ?? null; $inv = $data['invoices'] ?? array(); $days = $c ? (int)($c['betaling']['betalingsdage'] ?? 0) : 0;
	$stTxt = array('paid' => array(bp_t('Betalt','Paid'), 'vr-ok'), 'pending' => array(bp_t('Afventer betaling','Awaiting payment'), 'vr-warn'), 'overdue' => array(bp_t('Forfalden','Overdue'), 'vr-bad'));
	$open = 0; $openN = 0; $rows = array(); foreach ($inv as $i) { list($st, $due, $tot) = bill_classify($i, $days); if ($st != 'paid') { $open += $tot; $openN++; } $rows[] = array($i, $st, $due, $tot); }
	print "<div class=\"vr-grid2\"><section class=\"vr-sect\"><h2>".bp_t('Firmaets betalinger til Saldi','The firm\'s payments to Saldi')."</h2><div class=\"vr-card vr-kv\"><div><span>".bp_t('Udestående','Outstanding')."</span><b>".($openN ? number_format($open, 2, ',', '.')." DKK <span class=\"vr-mut2\">· $openN ".bp_t('fakturaer','invoices')."</span>" : '0,00 DKK')."</b></div><div><span>".bp_t('Betalingsbetingelser','Payment terms')."</span><b>".($c ? bp_h(($c['betaling']['betalingsbet'] ?? '–').' '.$days.' '.bp_t('dage','days')) : '–')."</b></div><div><span>".bp_t('Faktureringskunde','Billing customer')."</span><b>".($c ? bp_h($c['firmanavn'] ?? '')." <span class=\"vr-mut2\">· ".bp_t('kundenr.','no.')." ".bp_h($c['kontonr'])."</span>" : '<span class="vr-mut2">'.bp_t('ikke fundet','not found').'</span>')."</b></div><div><span>".bp_t('Faktura-e-mail','Invoice e-mail')."</span><b>".bp_h($p['billing_email'] ?: ($c['email'] ?? '–'))."</b></div></div>".(isset($data['error']) ? "<p class=\"bp-sub\" style=\"margin-top:10px;color:var(--warn-ink)\">".bp_h($data['error'])."</p>" : "")."</section>";
	print "<section class=\"vr-sect\"><h2>".bp_t('Faktureringsoplysninger','Billing details')."</h2><div class=\"vr-card vr-kv\"><div><span>".bp_t('Firma','Firm')."</span><b>".bp_h($p['name'])."</b></div><div><span>CVR</span><b>".bp_h($p['cvr'] ?: '–')."</b></div><div><span>".bp_t('Reference','Reference')."</span><b>".bp_h($p['billing_ref'] ?: '–')."</b></div><div><span>".bp_t('Betalingskanal','Payment channel')."</span><b>".($c && !empty($c['pbs']['active']) ? 'Betalingsservice' : ($c && !empty($c['stripe']['status']) ? bp_t('Kort på fil','Card on file') : bp_t('Faktura','Invoice')))."</b></div></div><div class=\"vr-foot\" style=\"margin-top:0\"><span>".bp_t('Ret faktura-e-mail og reference under Firmaoplysninger. Betalingskort og ændringer i aftalen: kontakt Saldi.','Edit invoice e-mail and reference under Firm details. Payment cards and agreement changes: contact Saldi.')."</span></div></section></div>";
	print "<section class=\"vr-sect\" style=\"margin-top:22px\"><h2>".bp_t('Fakturaer','Invoices')." <small>".count($rows)."</small></h2><div class=\"vr-card\"><table class=\"vr-t\"><thead><tr><th>".bp_t('Faktura','Invoice')."</th><th>".bp_t('Dato','Date')."</th><th>".bp_t('Forfald','Due')."</th><th class=\"vr-r\">".bp_t('Beløb inkl. moms','Amount incl. VAT')."</th><th>".bp_t('Status','Status')."</th></tr></thead><tbody>";
	foreach ($rows as $r) { list($i, $st, $due, $tot) = $r; print "<tr><td class=\"vr-nm\"><a>#".bp_h($i['invoiceNo'] ?? $i['orderNo'] ?? '-')."</a></td><td class=\"vr-mut\">".bp_date($i['invoiceDate'] ?? '')."</td><td class=\"vr-mut\">".bp_date($due)."</td><td class=\"vr-r vr-num\">".number_format($tot, 2, ',', '.')."</td><td><span class=\"vr-st\"><span class=\"vr-dot ".$stTxt[$st][1]."\"></span>".$stTxt[$st][0]."</span></td></tr>"; }
	if (!$rows) print "<tr><td colspan=\"5\" class=\"vr-mut\" style=\"padding:20px\">".(isset($data['error']) ? bp_t('Fakturaerne kunne ikke hentes fra Saldi lige nu.','The invoices could not be fetched from Saldi right now.') : bp_t('Ingen fakturaer endnu.','No invoices yet.'))."</td></tr>";
	print "</tbody></table></div></section>";

} else {
	$rows = bp_log_rows("(l.actor_partner_id = '$pid' or l.partner_id = '$pid' or l.regnskab_id in (select regnskab_id from regnskab_partners where partner_id = '$pid'))", 300);
	print "<section class=\"vr-sect\"><h2>".bp_t('Historik','History')." <small>".bp_t('adgang, brugere og abonnementer på tværs af firmaet','access, users and subscriptions across the firm')."</small></h2><div class=\"vr-card\"><table class=\"vr-t\"><thead><tr><th>".bp_t('Tidspunkt','Time')."</th><th>".bp_t('Hvem','Who')."</th><th>".bp_t('Hvad','What')."</th><th>".bp_t('Regnskab','Account')."</th><th>".bp_t('Detaljer','Details')."</th><th>".bp_t('Træder i kraft','Takes effect')."</th></tr></thead><tbody>";
	foreach ($rows as $l) print "<tr><td class=\"vr-mut vr-num\">".bp_h(substr($l['ts'], 0, 16))."</td><td>".bp_h($l['uname'] ?: $l['brugernavn'])." <span class=\"vr-mut2\">(".($l['pname'] ? bp_h($l['pname']) : 'Saldi').")</span></td><td>".bp_h(bp_action_label($l['action']))."</td><td class=\"vr-mut\">".($l['regnskab_id'] ? "<a href=\"bogholder_panel.php?regnskab_id=".(int)$l['regnskab_id']."\">".bp_h($l['regnskab'] ?: '#'.$l['regnskab_id'])."</a>" : '–')."</td><td class=\"vr-mut\">".bp_h($l['details'])."</td><td class=\"vr-mut\">".(($ef = bp_effective_from_details($l['details'])) ? bp_date($ef) : '–')."</td></tr>";
	if (!$rows) print "<tr><td colspan=\"6\" class=\"vr-mut\" style=\"padding:20px\">".bp_t('Ingen hændelser endnu','No events yet')."</td></tr>";
	print "</tbody></table></div></section>";
}
bp_close();
